<?php
declare(strict_types=1);

namespace Nelson\Resizer;

/**
 * Signs resizer URLs (HMAC-SHA256 of the file and params), so only thumbnails generated by the application
 * can be requested - an attacker can't fill the disk/CPU with arbitrary params combinations.
 * The format is not signed: it is limited to a few supported values and rewriteHtml() fills it in stored URLs.
 * Disabled when no secret is configured.
 */
final class UrlSigner
{
	/** Name of the query parameter (and of the presenter action parameter) carrying the signature */
	public const string PARAMETER = 's';

	/** Signature length in bytes before encoding (128 bits, 22 base64url characters) */
	private const int LENGTH = 16;


	public function __construct(
		private readonly ResizerConfig $config,
	) {
	}


	public function isEnabled(): bool
	{
		return $this->config->getSecret() !== null;
	}


	/**
	 * Signature of the thumbnail URL, null when signing is disabled.
	 */
	public function sign(string $file, ?string $params): ?string
	{
		$secret = $this->config->getSecret();

		if ($secret === null) {
			return null;
		}

		$hash = hash_hmac('sha256', self::getPayload($file, $params), $secret, true);
		return rtrim(strtr(base64_encode(substr($hash, 0, self::LENGTH)), '+/', '-_'), '=');
	}


	/**
	 * Always true when signing is disabled.
	 */
	public function verify(string $file, ?string $params, ?string $signature): bool
	{
		$expected = $this->sign($file, $params);

		if ($expected === null) {
			return true;
		}

		return $signature !== null && hash_equals($expected, $signature);
	}


	private static function getPayload(string $file, ?string $params): string
	{
		// the same thumbnail for "/a.jpg" and "a.jpg", and for null and the route default "auto";
		// the length prefix keeps the boundary between file and params unambiguous
		$file = ltrim($file, '/');
		return 'v1:' . strlen($file) . ':' . $file . ':' . ($params ?? ResizerLinkGenerator::PARAMS_AUTO);
	}
}
